	var wait sync.WaitGroup
	var firstErr error
	var errMu sync.Mutex
	for index, item := range items {
		wait.Add(1)
		go func(index int, item any) {
			defer wait.Done()
			select {
			case sem <- struct{}{}:
			case <-batchCtx.Done():
				return
			}
			defer func() { <-sem }()
			inputs := map[string]any{"item": item}
			capture := &captureEmitter{values: make(map[string]any)}
			observationID := fmt.Sprintf("%s:batch:%d", parent.input.ObservationID, index)
			child, childErr := newRunState(graph.fields, graphInputFromNodeInputs(inputs, observationID), inputs, capture)
			if childErr == nil {
				childErr = graph.execute(batchCtx, child)
			}
			if childErr != nil {
				errMu.Lock()
				if firstErr == nil {
					firstErr = fmt.Errorf("item %d: %w", index, childErr)
					cancel()
				}
				errMu.Unlock()
				return
			}
			primary, ok := capture.values[graph.primary.Name]
			if !ok {
				errMu.Lock()
				if firstErr == nil {
					firstErr = fmt.Errorf("item %d produced no primary output", index)
					cancel()
				}
				errMu.Unlock()
				return
			}
			results[index] = primary
		}(index, item)
	}
	wait.Wait()
	if firstErr != nil {
		return nil, nil, firstErr
	}
	return map[string]any{"items": results}, nil, nil
}

